import datetime


def _is_workday(d, holidays):
    return d.weekday() < 5 and d not in holidays


def _normalize_holidays(holidays):
    # Accept any collection of dates; use a set for fast lookup without
    # changing the caller's collection. Only dates matter (a holiday on a
    # weekend changes nothing, but weekday check already handles that).
    return set(holidays)


def add_workdays(start, days, holidays=()):
    """The date `days` working days from `start`. See TASK.md."""
    if isinstance(days, bool) or not isinstance(days, int):
        raise TypeError("days must be an int")

    hs = _normalize_holidays(holidays)

    if days == 0:
        if _is_workday(start, hs):
            return start
        # first working day after start
        cur = start
        while True:
            cur = cur + datetime.timedelta(days=1)
            if _is_workday(cur, hs):
                return cur

    step = 1 if days > 0 else -1
    remaining = abs(days)
    cur = start
    while remaining > 0:
        cur = cur + datetime.timedelta(days=step)
        if _is_workday(cur, hs):
            remaining -= 1
    return cur


def count_workdays(first, last, holidays=()):
    """Working days from `first` to `last`, both included. See TASK.md."""
    hs = _normalize_holidays(holidays)

    if first > last:
        return -count_workdays(last, first, holidays)

    total = 0
    cur = first
    one = datetime.timedelta(days=1)
    while cur <= last:
        if _is_workday(cur, hs):
            total += 1
        cur = cur + one
    return total
